class wf_bitacoraActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('wf_bitacora', 'list');
  }




  public function executeList()
  {
    $c = new Criteria();  	
	$this->myInstancia=WfInstanciaPeer::retrieveByPK($this->getRequestParameter('instancia_id'));
	
	
    $this->logged_user = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    	
	
	$instancia_id=$this->getRequestParameter('instancia_id');
	if($instancia_id>0){
	   $c->setDistinct();
	   $c->add(WfInstanciaBitacoraPeer::WFINSTANCIA_ID,$instancia_id);
	}
	$this->wf_instancia_bitacoras = WfInstanciaBitacoraPeer::doSelect( $c);
    $this->forward404Unless($this->myInstancia);
    
    
  }

  public function executeShow()
  {
    $this->wf_instancia_bitacora = WfInstanciaBitacoraPeer::retrieveByPk($this->getRequestParameter('wfinstanciabitacora_id'));
    $this->generada_tipo=$this->getRequestParameter('generada_tipo');
    $this->generada_msg =$this->getRequestParameter('generada_msg');
    $instancia_id =$this->wf_instancia_bitacora->getWfinstanciaId() ;
    $this->wfinstancia_id=$instancia_id;
    $myInstancia=WfInstanciaPeer::retrieveByPK($instancia_id);
    $this->esta_abierta=true;
    if($myInstancia->getWfInstanciaId()>0 ){
		$this->esta_abierta=$myInstancia->getEstaAbierta();    
	}
    
    
    $this->forward404Unless($this->wf_instancia_bitacora);
  }

  public function executeCreate()
  {
    $this->wf_instancia_bitacora = new WfInstanciaBitacora();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    //
    $this->consulta=Array();
    //getLista_Transiciones
    
    $this->wf_instancia_bitacora = WfInstanciaBitacoraPeer::retrieveByPk($this->getRequestParameter('wfinstanciabitacora_id'));
    if($this->wf_instancia_bitacora){
	
	$instancia_id =$this->wf_instancia_bitacora->getWfinstanciaId() ;
    $this->wfinstancia_id=$instancia_id;
    
    if($instancia_id>0){
	$myIfz = new wf_Interface();
    $this->consulta = $myIfz->getRSTransiciones( $instancia_id );
    $this->esta_abierta=true;
    $this->esta_abierta=$myIfz->getEstaAbiertaInstancia($instancia_id);
    
    if( count($this->consulta)==0 ){
		//cerrarla pues NO tiene mas transiciones...
		$myIfz->cierraInstanciaIncondicionalmente($instancia_id);
		
	}
    
    $this->requiereComunicacion=$myIfz->getRequiereComunicacion($instancia_id);
    $this->requiere_interna=$myIfz->getRequiereInterna($instancia_id);
    $this->requiere_recibida=$myIfz->getRequiereRecibida($instancia_id);
    $this->requiere_enviada=$myIfz->getRequiereEnviada($instancia_id);
    
    $this->myEnviadaId=$this->wf_instancia_bitacora->getComEnviadaId();
    $this->myInternaId=$this->wf_instancia_bitacora->getComInternaId();
    $this->myRecibidaId=$this->wf_instancia_bitacora->getComRecibidaId();
    
    $this->granted_users=$myIfz->getArrayGrantedUsers($instancia_id);
    
    
    $this->logged_user = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    	
	}
	
		
		
	} 
    
    
    
    $this->forward404Unless($this->wf_instancia_bitacora);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('wfinstanciabitacora_id'))
    {
      $wf_instancia_bitacora = new WfInstanciaBitacora();
    }
    else
    {
      $wf_instancia_bitacora = WfInstanciaBitacoraPeer::retrieveByPk($this->getRequestParameter('wfinstanciabitacora_id'));
      $this->forward404Unless($wf_instancia_bitacora);
    }
    
    $generada_tipo=$this->getRequestParameter('generada_tipo');
    $generada_msg = $this->getRequestParameter('generada_msg');
    
    
    
    $instancia_id = $wf_instancia_bitacora->getWfinstanciaId() ;
    if($instancia_id>0  && $this->getRequestParameter('proximoUsuario')>0 &&  $this->getRequestParameter('transicion_id')>0){
		 /* wf begin */
         $nudebug=1;
         $usuario         = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');	
         $usuario_destino = $this->getRequestParameter('proximoUsuario');	
         $observaciones   = $this->getRequestParameter('observaciones');
         $transicion_id   = $this->getRequestParameter('transicion_id');
         
         $myIfz = new wf_Interface();
         $result=$myIfz->closecurrentActividad($instancia_id, $usuario_destino, $observaciones, $transicion_id);
         if( $nudebug )
            echo ">>>>>>>>" . $instancia_id . " ". $result ."<<<<<<<<<";
         /* wf end */
         return $this->redirect($this->getRequest()->getScriptName().'/wf_bitacora/show?wfinstanciabitacora_id='.$wf_instancia_bitacora->getWfinstanciabitacoraId() );
    }else{
		 return $this->redirect($this->getRequest()->getScriptName().'/wf_bitacora/edit?wfinstanciabitacora_id='.$wf_instancia_bitacora->getWfinstanciabitacoraId() );
		
	}	

    
  }

  public function executeDelete()
  {
    $wf_instancia_bitacora = WfInstanciaBitacoraPeer::retrieveByPk($this->getRequestParameter('wfinstanciabitacora_id'));

    $this->forward404Unless($wf_instancia_bitacora);

    $wf_instancia_bitacora->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/wf_bitacora/list');
  }
}
